-- =============================================================================
-- 481 — LE CAHIER D'EXERCICES DE 5E (partie 10)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/5e/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 481 --niveau 5e --fichiers technologie.k227 --suffixe 10 > supabase/contenu/481_exercices_5e_10.sql
--
-- 33 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   technologie.k227        33 exercices · 11 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('a433ef1c-1939-5770-92fd-e7a7682ce4ed'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Quatre objets, quatre mécanismes","competence":"analyser-document","situation":"Lors d’une visite de l’atelier, Léa relève le mécanisme qui équipe quatre objets du quotidien.","documents":[{"id":"objets","type":"fiche","modele":"ticket","entete":"Les objets de la visite","sousTitre":"Objet et mécanisme","emoji":"🔧","lignes":[{"texte":"Portail coulissant","valeur":"Pignon-crémaillère","id":"z1"},{"texte":"Vélo","valeur":"Pignons-chaîne","id":"z2"},{"texte":"Étau d’établi","valeur":"Vis-écrou","id":"z3"},{"texte":"Moteur de voiture","valeur":"Bielle-manivelle","id":"z4"}],"pied":"Situation imaginée pour l’exercice"}],"questions":[{"enonce":"Touche l’objet dont le mécanisme transmet un mouvement sans changer sa nature.","aide":"Sur un vélo, le pédalier tourne et la roue arrière tourne aussi.","type":"zone","document":"objets","multiple":false},{"enonce":"Range chaque mécanisme : transmet-il ou transforme-t-il le mouvement ?","aide":"Un mécanisme qui transforme change une rotation en translation.","type":"categories","categories":[{"id":"c0","texte":"Transmettre"},{"id":"c1","texte":"Transformer"}],"items":[{"id":"i0","texte":"Engrenages"},{"id":"i1","texte":"Poulies-courroie"},{"id":"i2","texte":"Pignon-crémaillère"},{"id":"i3","texte":"Vis-écrou"},{"id":"i4","texte":"Bielle-manivelle"},{"id":"i5","texte":"Pignons-chaîne"}]},{"enonce":"Le pignon tourne et le portail glisse le long de son rail. Quel est le mouvement de sortie ?","aide":"Le portail avance en ligne droite, sans tourner sur lui-même.","type":"choix","options":[{"id":"a","texte":"Une rotation à vitesse réduite, comme celle du pignon mais plus lente"},{"id":"b","texte":"Une rotation autour d’un axe, comme le ferait une porte sur ses gonds"},{"id":"c","texte":"Aucun mouvement : le portail reste fixe pendant que le pignon tourne"},{"id":"d","texte":"Une translation : le portail se déplace en ligne droite sans tourner"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Sur le **vélo**, la rotation du pédalier devient une rotation de la roue : le mouvement est **transmis**, sa nature ne change pas."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1","i4":"c1","i5":"c0"}},"explication":"**Transmettre** : engrenages, poulies-courroie, pignons-chaîne (la rotation reste une rotation). **Transformer** : pignon-crémaillère, vis-écrou, bielle-manivelle (la nature du mouvement change)."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le portail se déplace sans tourner : c’est une **translation**. Le pignon-crémaillère transforme la rotation en translation."}]$ex$::jsonb),
  ('a433ef1c-1939-5770-92fd-e7a7682ce4ed'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les vitesses du VTT de Noa","competence":"calculer","situation":"Noa change de vitesse sur son VTT. Le plateau du pédalier a toujours 32 dents ; seul le pignon de la roue arrière change.","documents":[{"id":"vit","type":"tableau","titre":"Les trois vitesses du VTT","colonnes":["Vitesse","Dents du plateau (entrée)","Dents du pignon arrière (sortie)"],"lignes":[["1",32,40],["2",32,32],["3",32,16]],"enteteLignes":true,"source":"Situation imaginée pour l’exercice"}],"questions":[{"enonce":"Calcule le rapport de transmission r de la vitesse 1 (dents de l’entrée ÷ dents de la sortie).","aide":"Divise 32 par 40.","type":"nombre"},{"enonce":"Range les trois vitesses de la plus adaptée à une côte à la moins adaptée.","aide":"Dans une côte on veut de la force : cherche le plus petit r.","type":"ordre","items":[{"id":"a","texte":"Vitesse 2"},{"id":"b","texte":"Vitesse 3"},{"id":"c","texte":"Vitesse 1"}]},{"enonce":"En vitesse 3, le pédalier tourne à 60 tours par minute. À quelle vitesse tourne la roue arrière ?","aide":"Calcule d’abord r pour la vitesse 3, puis multiplie par 60.","type":"nombre","unite":"tr/min"},{"enonce":"En vitesse 2, que peut-on dire du mécanisme ?","aide":"Calcule r pour la vitesse 2.","type":"choix","options":[{"id":"a","texte":"Il ne transmet pas le mouvement"},{"id":"b","texte":"C’est un multiplicateur"},{"id":"c","texte":"C’est un réducteur"},{"id":"d","texte":"Il ne change pas la vitesse : r = 1"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":0.8,"tolerance":0},"affichage":"0,8","explication":"r = 32 ÷ 40 = **0,8**. Comme r < 1, c’est un réducteur."},{"cle":{"type":"ordre","ids":["c","a","b"]},"explication":"Vitesse 1 : r = 0,8 ; vitesse 2 : r = 1 ; vitesse 3 : r = 2. Plus r est **petit**, plus on gagne en force : **1, 2, 3**."},{"cle":{"type":"nombre","valeur":120,"tolerance":0},"affichage":"120 tr/min","explication":"r = 32 ÷ 16 = 2, donc la roue tourne à 60 × 2 = **120 tr/min** : c’est un multiplicateur."},{"cle":{"type":"choix","ids":["d"]},"explication":"r = 32 ÷ 32 = **1** : la roue tourne aussi vite que le pédalier. Ce n’est ni un réducteur ni un multiplicateur."}]$ex$::jsonb),
  ('a433ef1c-1939-5770-92fd-e7a7682ce4ed'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le portail qui coulisse tout seul","competence":"raisonner","situation":"Un portail de résidence est entraîné par un moteur. Un premier étage réduit la vitesse, puis un second étage déplace le portail.","documents":[{"id":"chaine","type":"chaine","titre":"La transmission du portail","disposition":"ligne","noeuds":[{"id":"z1","texte":"Moteur","emoji":"⚙️"},{"id":"z2","texte":"Pignons-chaîne","emoji":"⛓️"},{"id":"z3","texte":"Pignon-crémaillère","emoji":"🔩"},{"id":"z4","texte":"Portail","emoji":"🚪"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"}],"source":"Situation imaginée pour l’exercice"},{"id":"fichetech","type":"fiche","modele":"ticket","entete":"Fiche technique","sousTitre":"Motorisation","emoji":"📋","lignes":[{"texte":"Vitesse du moteur","valeur":"1 200 tr/min"},{"texte":"Pignon moteur","valeur":"12 dents"},{"texte":"Pignon récepteur","valeur":"48 dents"},{"texte":"Transmission","valeur":"Par chaîne"}],"pied":"Situation imaginée pour l’exercice"}],"questions":[{"enonce":"Touche le mécanisme qui transforme la rotation en translation.","aide":"Le portail avance en ligne droite.","type":"zone","document":"chaine","multiple":false},{"enonce":"Calcule le rapport de transmission r du premier étage (dents de l’entrée ÷ dents de la sortie).","aide":"L’entrée est le pignon moteur.","type":"nombre"},{"enonce":"À quelle vitesse tourne le pignon récepteur ?","aide":"Multiplie la vitesse du moteur par r.","type":"nombre","unite":"tr/min"},{"enonce":"Que dire du premier étage ?","aide":"Compare r à 1.","type":"choix","options":[{"id":"a","texte":"C’est un réducteur : la vitesse de rotation baisse et la force augmente"},{"id":"b","texte":"Il ne change ni la vitesse ni la force, il transmet seulement le mouvement"},{"id":"c","texte":"C’est un multiplicateur : la vitesse de rotation augmente et la force baisse"},{"id":"d","texte":"Il change la rotation en translation, comme le ferait une crémaillère"}],"multiple":false},{"enonce":"Le pignon moteur tourne dans le sens des aiguilles d’une montre. Dans quel sens tourne le pignon récepteur ?","aide":"Pense au vélo.","type":"choix","options":[{"id":"a","texte":"En sens inverse"},{"id":"b","texte":"Il ne tourne pas"},{"id":"c","texte":"Cela dépend du nombre de dents"},{"id":"d","texte":"Dans le même sens"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"Le **pignon-crémaillère** change la rotation du pignon en translation de la crémaillère fixée au portail."},{"cle":{"type":"nombre","valeur":0.25,"tolerance":0},"affichage":"0,25","explication":"r = 12 ÷ 48 = **0,25**."},{"cle":{"type":"nombre","valeur":300,"tolerance":0},"affichage":"300 tr/min","explication":"1 200 × 0,25 = **300 tr/min**."},{"cle":{"type":"choix","ids":["a"]},"explication":"r < 1 : c’est un **réducteur**. Le portail est lourd, il faut de la force plutôt que de la vitesse."},{"cle":{"type":"choix","ids":["d"]},"explication":"Avec une **chaîne**, les deux pignons tournent dans le **même sens**."}]$ex$::jsonb),
  ('86f0c251-3a05-5a35-b4e7-8741c482bde4'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"L’atelier de Sacha","competence":"analyser-document","situation":"Sacha range l’atelier et étiquette cinq objets avec leur matériau.","documents":[{"id":"objets","type":"fiche","modele":"ticket","entete":"Étiquettes de l’atelier","sousTitre":"Objet et matériau","emoji":"🏷️","lignes":[{"texte":"Fourchette","valeur":"Acier","id":"z1"},{"texte":"Règle","valeur":"Plastique","id":"z2"},{"texte":"Mug","valeur":"Porcelaine","id":"z3"},{"texte":"Clé","valeur":"Laiton","id":"z4"},{"texte":"Raquette","valeur":"Fibre de carbone","id":"z5"}],"pied":"Situation imaginée pour l’exercice"}],"questions":[{"enonce":"Touche les deux objets en matériau métallique.","aide":"L’acier et le laiton sont des alliages de métaux.","type":"zone","document":"objets","multiple":true},{"enonce":"Associe chaque matériau à son atout principal.","aide":"Pense à la famille de chaque matériau.","type":"association","gauche":[{"id":"g0","texte":"Acier"},{"id":"g1","texte":"Plastique"},{"id":"g2","texte":"Porcelaine"},{"id":"g3","texte":"Fibre de carbone"}],"droite":[{"id":"d0","texte":"Cumule les qualités de deux matériaux"},{"id":"d1","texte":"Léger et facile à mettre en forme"},{"id":"d2","texte":"Résistant et recyclable"},{"id":"d3","texte":"Très dure mais fragile"}]},{"enonce":"Pourquoi une raquette est-elle en fibre de carbone ?","aide":"La raquette doit être légère et ne pas plier.","type":"choix","options":[{"id":"a","texte":"C’est une céramique très dure, choisie pour sa légèreté et sa solidité"},{"id":"b","texte":"C’est un métal très conducteur, choisi pour sa légèreté et sa solidité"},{"id":"c","texte":"C’est un plastique simple recyclable indéfiniment, sans perte de qualité"},{"id":"d","texte":"C’est un composite : il associe légèreté et grande résistance mécanique"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1","z4"]},"explication":"L’**acier** et le **laiton** sont métalliques. La règle est en plastique, le mug en céramique, la raquette en composite."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g0":"d2","g2":"d3"}},"explication":"Métal : résistant et recyclable. Plastique (organique) : léger, facile à façonner. Céramique : dure mais **fragile**. Composite : **cumule** les qualités."},{"cle":{"type":"choix","ids":["d"]},"explication":"La fibre de carbone est un **composite** : elle cumule la légèreté et la résistance de ses deux constituants."}]$ex$::jsonb),
  ('86f0c251-3a05-5a35-b4e7-8741c482bde4'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le cadre du vélo d’Anaïs","competence":"calculer","situation":"Anaïs veut un cadre léger, recyclable et pas trop cher. Elle compare quatre matériaux.","documents":[{"id":"masse","type":"graphique","forme":"barres-h","titre":"Masse volumique","categories":["Acier","Aluminium","Fibre de carbone","ABS (plastique)"],"series":[{"nom":"Masse volumique","valeurs":[7.8,2.7,1.6,1.05],"teinte":"gris"}],"axeY":{"titre":"Masse volumique","unite":"g/cm³","min":0,"max":8,"pas":2},"valeurs":false,"source":"Valeurs arrondies"},{"id":"prix","type":"tableau","titre":"Prix et recyclage","colonnes":["Matériau","Prix (€/kg)","Se recycle ?"],"lignes":[["Acier",1,"Bien"],["Aluminium",3,"Bien"],["Fibre de carbone",25,"Non"],["ABS (plastique)",2,"Difficilement"]],"enteteLignes":true,"source":"Valeurs arrondies, ordres de grandeur"}],"questions":[{"enonce":"Touche le matériau le plus léger de la liste.","aide":"Plus la masse volumique est petite, plus le matériau est léger.","type":"zone","document":"masse","multiple":false},{"enonce":"Le cadre a un volume de 500 cm³. Quelle serait sa masse en aluminium ?","aide":"Masse = masse volumique × volume.","type":"nombre","unite":"g"},{"enonce":"Un cadre en fibre de carbone de 1,2 kg. Quel est le coût de la matière ?","aide":"Multiplie le prix au kilo par la masse.","type":"nombre","unite":"€"},{"enonce":"Anaïs veut un cadre léger, recyclable et peu cher. Quel matériau choisir ?","aide":"Élimine ceux qui ne se recyclent pas bien ou qui sont trop lourds.","type":"choix","options":[{"id":"a","texte":"L’aluminium"},{"id":"b","texte":"L’ABS"},{"id":"c","texte":"La fibre de carbone"},{"id":"d","texte":"L’acier"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k3"]},"explication":"L’**ABS** a la plus petite masse volumique (1,05 g/cm³) : c’est le plus léger."},{"cle":{"type":"nombre","valeur":1350,"tolerance":0},"affichage":"1350 g","explication":"2,7 × 500 = **1 350 g**, soit 1,35 kg."},{"cle":{"type":"nombre","valeur":30,"tolerance":0},"affichage":"30 €","explication":"25 × 1,2 = **30 €**."},{"cle":{"type":"choix","ids":["a"]},"explication":"L’acier est lourd, la fibre de carbone est chère et ne se recycle pas, l’ABS se recycle difficilement. L’**aluminium** est léger, recyclable et abordable."}]$ex$::jsonb),
