  ('56818234-bc89-53fb-89f2-a0fc31419086'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le thermomètre d’Inès","competence":"analyser-document","situation":"Inès a construit un thermomètre électronique avec une carte programmable. Elle note le rôle de chaque composant.","documents":[{"id":"thermo","type":"fiche","modele":"ticket","entete":"Le thermomètre d’Inès","sousTitre":"Composants et rôles","emoji":"🌡️","lignes":[{"texte":"Thermistance","valeur":"Mesure la température","id":"z1"},{"texte":"Bouton-poussoir","valeur":"Change l’unité °C / °F","id":"z2"},{"texte":"Carte programmable","valeur":"Exécute le programme","id":"z3"},{"texte":"Écran","valeur":"Affiche la valeur","id":"z4"},{"texte":"Buzzer","valeur":"Sonne au-dessus de 30 °C","id":"z5"}],"pied":"Situation imaginée pour l’exercice"}],"questions":[{"enonce":"Touche les deux composants qui prennent une information : ce sont les capteurs.","aide":"Un capteur recueille une information ; il ne la décide pas et ne l’affiche pas.","type":"zone","document":"thermo","multiple":true},{"enonce":"Range dans l’ordre le trajet de l’information quand la température monte.","aide":"On mesure, on décide, puis on signale.","type":"ordre","items":[{"id":"a","texte":"La thermistance mesure la température"},{"id":"b","texte":"Le buzzer sonne"},{"id":"c","texte":"La carte compare la mesure à 30 °C"}]},{"enonce":"Le buzzer sonne quand il fait plus de 30 °C. À quelle fonction de la chaîne d’information correspond-il ?","aide":"Il prévient l’utilisateur.","type":"choix","options":[{"id":"a","texte":"Communiquer l’information"},{"id":"b","texte":"Traiter l’information reçue"},{"id":"c","texte":"Acquérir l’information"},{"id":"d","texte":"Mesurer la température"}],"multiple":false}]}$ex$::jsonb,
