   $ex${"titre":"La serre qui arrose","competence":"analyser-document","situation":"Une serre est équipée d’un arrosage automatique. Elle envoie aussi un message sur le téléphone du jardinier.","documents":[{"id":"chaine","type":"chaine","titre":"La chaîne d’information de la serre","disposition":"ligne","noeuds":[{"id":"z1","texte":"Capteur d’humidité","emoji":"💧"},{"id":"z2","texte":"?"},{"id":"z3","texte":"Envoi Wi-Fi vers le téléphone","emoji":"📱"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"}],"source":"Situation imaginée pour l’exercice"},{"id":"releves","type":"tableau","titre":"Relevés de la journée","colonnes":["Heure","8 h","12 h","16 h"],"lignes":[["Humidité du sol (%)",62,38,25]],"enteteLignes":true,"source":"Le programme déclenche l’arrosage quand l’humidité passe sous 30 %."}],"questions":[{"enonce":"Touche l’élément qui communique l’information au jardinier.","aide":"Il transmet l’information vers l’extérieur du système.","type":"zone","document":"chaine","multiple":false},{"enonce":"Quel composant faut-il placer à la place du « ? » pour décider d’arroser ?","aide":"C’est la fonction « traiter » : il exécute un programme.","type":"choix","options":[{"id":"a","texte":"Un bouton-poussoir"},{"id":"b","texte":"Une lampe"},{"id":"c","texte":"Un moteur"},{"id":"d","texte":"Un microcontrôleur"}],"multiple":false},{"enonce":"À quelle heure l’arrosage se déclenche-t-il pour la première fois ? (réponds en heures, ex. 8)","aide":"Cherche la première mesure sous 30 %.","type":"nombre","unite":"h"},{"enonce":"Associe chaque capteur à la grandeur qu’il mesure.","aide":"Le nom du capteur donne souvent un indice.","type":"association","gauche":[{"id":"g0","texte":"Photorésistance"},{"id":"g1","texte":"Capteur à ultrasons"},{"id":"g2","texte":"Thermistance"},{"id":"g3","texte":"Fin de course"}],"droite":[{"id":"d0","texte":"La position"},{"id":"d1","texte":"La lumière"},{"id":"d2","texte":"La température"},{"id":"d3","texte":"La distance"}]}]}$ex$::jsonb,
